interface Criteria {
  isSatisfiedBy(product: Product): boolean;
  and(other: Criteria): Criteria;
}

abstract class BaseCriteria implements Criteria {
  abstract isSatisfiedBy(product: Product): boolean;
  and(other: Criteria): Criteria {
    return { isSatisfiedBy: (p) => this.isSatisfiedBy(p) && other.isSatisfiedBy(p), and: this.and };
  }
}

class InStock extends BaseCriteria {
  isSatisfiedBy(p: Product) { return p.stock > 0; }
}
class OnSale extends BaseCriteria {
  isSatisfiedBy(p: Product) { return p.onSale; }
}

function filter(products: Product[], criteria: Criteria) {
  return products.filter((p) => criteria.isSatisfiedBy(p));
}

// Any combination composes from existing pieces — no new function needed
filter(products, new InStock().and(new OnSale()));
